/**
 * `Cloudflare.Env` is generated by `wrangler types` from wrangler.jsonc (worker-configuration.d.ts,
 * written by the typecheck script and ignored by git), so a renamed binding, var or secret fails
 * the typecheck instead of failing at runtime. Vars and secrets are documented in wrangler.jsonc.
 * Only settings that are not in the config file are declared here.
 */
export interface Env extends Cloudflare.Env {
  /** Secret that signs guest passes (32+ random characters). Unset: a development key, with a warning. */
  PASS_SIGNING_KEY?: string;
  /** Secret for admin routes (private tally, month close), 16+ characters. Unset: admin routes stay closed. */
  ADMIN_KEY?: string;
  /** Optional JSON object of per-room caps, e.g. {"hub":80,"grove":40}. */
  ROOM_CAPS?: string;
  /** Local load testing only: trust X-Forwarded-For as the client address. Never set in production. */
  TRUST_FORWARDED_FOR?: string;
  /**
   * Pages served somewhere else that may open the park's sockets and read its answers (src/guard.ts),
   * as origins separated by commas, e.g. "https://owner.github.io" for the client on GitHub Pages
   * (docs/DEPLOY.md mode A). Unset: only the park's own pages (and, on this machine, local ones).
   */
  PARK_ORIGINS?: string;
  /**
   * The store that sells tickets (C35): its myshopify domain, and the app the park signs in with:
   * a Dev Dashboard app's client ID and secret (traded for a token that lasts a day), or the fixed
   * Admin API token of an app made in the store's admin before 2026. Unset: the store's webhooks
   * are refused and nothing is copied to the store.
   */
  SHOPIFY_SHOP?: string;
  SHOPIFY_CLIENT_ID?: string;
  SHOPIFY_CLIENT_SECRET?: string;
  SHOPIFY_ADMIN_TOKEN?: string;
  /**
   * The key the store signs webhooks made in its admin with (Settings, Notifications, Webhooks).
   * Webhooks the app subscribes are signed with its client secret instead. Neither: every webhook is refused.
   */
  SHOPIFY_WEBHOOK_SECRET?: string;
  /**
   * Opening night (C42): the discount code that takes half off the annual pass (OP-062), never
   * advertised. The park puts it in the cart link it gives an owl whose Opening Night Ticket went
   * through the gate, and counts passes bought with it but without that link. Unset: no pass link.
   */
  OPENING_PASS_CODE?: string;
  /** Browser tests only: a stand-in store on this machine (http://localhost:<port>). Never set in production. */
  SHOPIFY_TEST_ORIGIN?: string;
  /**
   * The collection log (OP-107): the address of the `owl-park-log` function in the fraud pipeline's
   * Supabase project (apps/park-log). With FRAUD_SCORE_KEY (the key it checks, sent as a bearer
   * token) and FRAUD_HASH_SALT (which salts the collector and visit hashes), every collectible an owl
   * comes by is logged there; without all three nothing is logged. FRAUD_SCORE_URL is not involved:
   * the fraud link (OP-053) stays off without it.
   */
  PARK_LOG_URL?: string;
  FRAUD_SCORE_KEY?: string;
  FRAUD_HASH_SALT?: string;
  /**
   * Accounts without passwords (OP-139), with ACCOUNTS on (wrangler.jsonc). ACCOUNT_SECRET (32+ random
   * characters) keys the hash an email is found by and seals the copy the park writes to; it must
   * never change once owls are protected, or their emails are lost to the park. The magic links go
   * out through Resend: RESEND_API_KEY, from MAIL_FROM (a sender on a domain verified there). Without
   * all three no email is kept and no link is sent; friend codes and one screen at a time still work.
   */
  ACCOUNT_SECRET?: string;
  RESEND_API_KEY?: string;
  MAIL_FROM?: string;
  /** Browser tests only: a stand-in mail sender on this machine (http://localhost:<port>). Never set in production. */
  MAIL_TEST_ORIGIN?: string;
}
